"""Bienvenida neón animada. Compatible con MainWindow: start_requested.

No requiere imágenes ni bibliotecas adicionales fuera de PySide6.
Las ondas son decorativas; no representan datos adquiridos.
"""
from __future__ import annotations
from gui.theme.day_style import is_day, day_color

import math
from PySide6.QtCore import Qt, QTimer, Signal, QRectF, QElapsedTimer
from PySide6.QtGui import (QColor, QFont, QFontMetricsF, QPainter, QPainterPath,
                          QPen, QLinearGradient)
from PySide6.QtWidgets import QWidget, QPushButton


class WelcomePage(QWidget):
    start_requested = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setObjectName('welcomePage')
        self.setMinimumSize(540, 360)
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent)
        self.phase = 0.0
        self.speed = 5.2  # radianes por segundo; independiente de los FPS
        self._clock = QElapsedTimer()
        self._clock.start()
        self._last_ns = self._clock.nsecsElapsed()
        self.timer = QTimer(self)
        self.timer.setTimerType(Qt.TimerType.PreciseTimer)
        self.timer.setInterval(16)  # objetivo aproximado: 60 FPS
        self.timer.timeout.connect(self._animate)
        self.timer.start()

        # Botón real sobre el dibujo, centrado en la zona inferior.
        self.start_button = QPushButton('▶   INICIAR OSCILOSCOPIO', self)
        self.start_button.setObjectName('startButton')
        self.start_button.setCursor(Qt.CursorShape.PointingHandCursor)
        self.start_button.clicked.connect(self.start_requested.emit)
        self.start_button.setStyleSheet('''
            QPushButton#startButton {
                color: #F2FBFF; background: rgba(3, 27, 57, 235);
                border: 3px solid #00F0FF; border-radius: 28px;
                font-family: 'Segoe UI'; font-size: 19px; font-weight: 800;
            }
            QPushButton#startButton:hover {
                background: rgba(5, 78, 119, 240); border-color: #A9FFFF;
            }
            QPushButton#startButton:pressed { background: #08618D; }
        ''')
        self._font_cache_width = None
        self._title_font = None
        self._subtitle_font = None
        self._layout_button()
        self._scope_v4_original_button = self.start_button.styleSheet()
        self._scope_v4_refresh()
        # OSCILLOPONG_V1
        from gui.easter_egg.pong_game import install
        install(self)
        # OSCILLOTETRIS_V1
        from gui.easter_egg.tetris_game import install as install_tetris
        install_tetris(self)

    def _scope_v4_refresh(self):
        self.start_button.setStyleSheet(
            "QPushButton#startButton { color: #006E88; background: #FFFFFF; border: 2px solid #007F9C; border-radius: 28px; font-size: 19px; font-weight: 800; } QPushButton#startButton:hover { background: #D4EDF3; } QPushButton#startButton:pressed { background: #C0E3EC; }"
            if is_day() else self._scope_v4_original_button)
        self.update()

    def _animate(self):
        now_ns = self._clock.nsecsElapsed()
        dt = min((now_ns - self._last_ns) / 1_000_000_000, 0.05)
        self._last_ns = now_ns
        if self.isVisible():
            self.phase = (self.phase + self.speed * dt) % (2 * math.pi)
            self.update()

    def _layout_button(self):
        w, h = self.width(), self.height()
        bw = min(510, max(300, int(w * .37)))
        bh = max(52, min(78, int(h * .105)))
        self.start_button.setGeometry((w - bw) // 2, int(h * .85) - bh // 2, bw, bh)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._layout_button()
        self._font_cache_width = None

    def _fonts_for_width(self, w):
        if self._font_cache_width == w:
            return self._title_font, self._subtitle_font
        title = 'OSCILOSCOPIO'
        title_font = QFont('Arial', 100, QFont.Weight.Black)
        title_font.setLetterSpacing(QFont.SpacingType.PercentageSpacing, 100)
        while (QFontMetricsF(title_font).horizontalAdvance(title) > w * .78
               and title_font.pointSize() > 20):
            title_font.setPointSize(title_font.pointSize() - 1)
        subtitle = 'SISTEMA DE ADQUISICIÓN Y VISUALIZACIÓN DE SEÑALES'
        sub_font = QFont('Segoe UI', max(8, min(16, int(w / 95))), QFont.Weight.DemiBold)
        sub_font.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 2)
        while (QFontMetricsF(sub_font).horizontalAdvance(subtitle) > w * .90
               and sub_font.pointSize() > 7):
            sub_font.setPointSize(sub_font.pointSize() - 1)
        self._font_cache_width = w
        self._title_font = title_font
        self._subtitle_font = sub_font
        return title_font, sub_font

    @staticmethod
    def _glow_path(p, path, rgb, core=2.8):
        color = QColor(rgb)
        for width, alpha in (((core, 255),) if is_day() else ((15, 18), (7, 65), (core, 255))):
            c = QColor(color)
            c.setAlpha(alpha)
            p.setPen(QPen(c, width, Qt.PenStyle.SolidLine,
                          Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)

    def _wave(self, p, kind, y, amp, period, color, offset=0.0):
        w = self.width()
        path = QPainterPath()
        dx = 5
        for x in range(-dx, w + dx + 1, dx):
            theta = 2 * math.pi * x / period - self.phase + offset
            if kind == 'sine':
                value = math.sin(theta)
            elif kind == 'square':
                value = 1 if math.sin(theta) >= 0 else -1
            else:
                value = (2 / math.pi) * math.asin(math.sin(theta))
            py = y - amp * value
            if x == -dx:
                path.moveTo(x, py)
            else:
                # Para onda cuadrada, salto vertical limpio (sin diagonales).
                if kind == 'square' and x > -dx:
                    prev = math.sin(2 * math.pi * (x-dx) / period - self.phase + offset)
                    prev_val = 1 if prev >= 0 else -1
                    if prev_val != value:
                        path.lineTo(x, y - amp * prev_val)
                path.lineTo(x, py)
        self._glow_path(p, path, color)

    @staticmethod
    def _centered_text(p, text, cx, baseline, font, color, glow=None):
        p.setFont(font)
        fm = QFontMetricsF(font)
        x = cx - fm.horizontalAdvance(text) / 2
        if glow and not is_day():
            for shift, alpha in ((4, 30), (2, 65)):
                c = QColor(glow)
                c.setAlpha(alpha)
                p.setPen(c)
                for ox, oy in ((-shift, 0), (shift, 0), (0, -shift), (0, shift)):
                    p.drawText(int(x + ox), int(baseline + oy), text)
        p.setPen(QColor(color))
        p.drawText(int(x), int(baseline), text)

    # OSCILLO_ARCADE_DIM_V2
    def run_arcade_dialog(self, game):
        """Congela y atenúa la bienvenida mientras se juega."""
        from PySide6.QtCore import QVariantAnimation, QEasingCurve
        if getattr(self, '_arcade_active', False):
            return
        was_running = self.timer.isActive()
        was_hidden = self.start_button.isHidden()
        self.timer.stop()
        animation = None

        def restore():
            self._arcade_active = False
            self._arcade_snapshot = None
            self._arcade_dim = 0.0
            self._last_ns = self._clock.nsecsElapsed()
            self.start_button.setVisible(not was_hidden)
            if was_running:
                self.timer.start()
            self.update()

        def opacity_changed(value):
            self._arcade_dim = float(value)
            self.update()

        try:
            self._arcade_snapshot = self.grab()
            self._arcade_dim = 0.0
            self._arcade_active = True
            self.start_button.hide()
            self.repaint()
            animation = QVariantAnimation(self)
            animation.setDuration(250)
            animation.setEasingCurve(QEasingCurve.Type.InOutQuad)
            animation.setStartValue(0.0)
            animation.setEndValue(0.78)
            animation.valueChanged.connect(opacity_changed)
            animation.start()
            return game.exec()
        finally:
            if animation is not None and self.isVisible():
                animation.stop()
                current_dim = float(self._arcade_dim)
                animation.setStartValue(current_dim)
                animation.setEndValue(0.0)
                animation.finished.connect(restore)
                animation.finished.connect(animation.deleteLater)
                # Evita que Qt omita el fundido si el juego cerró al instante.
                if current_dim > 0.0:
                    animation.start()
                else:
                    restore()
                    animation.deleteLater()
            else:
                if animation is not None:
                    animation.stop()
                    animation.deleteLater()
                restore()

    def _draw_institution_logo(self, p, w, h):
        import base64
        from PySide6.QtGui import QPixmap
        if not hasattr(self, '_fi_logo'):
            self._fi_logo = QPixmap()
            self._fi_logo.loadFromData(base64.b64decode(''), 'PNG')
        if self._fi_logo.isNull():
            return
        # IDENTIDAD_ACADEMICA_FI_V2 / IDENTIDAD_ACADEMICA_FI_V3
        from PySide6.QtCore import QSettings
        from PySide6.QtGui import QImage
        day = QSettings('OsciloscopioPF', 'Osciloscopio').value('appearance/theme', 'dark') == 'light'
        if not hasattr(self, '_fi_crisp_cache'):
            self._fi_crisp_cache = {}
        if day not in self._fi_crisp_cache:
            src = self._fi_logo.toImage().convertToFormat(QImage.Format.Format_ARGB32)
            ink = QColor('#17617B' if day else '#B9F8FF')
            mask = QImage(src.size(), QImage.Format.Format_ARGB32)
            mask.fill(Qt.GlobalColor.transparent)
            left, top, right, bottom = src.width(), src.height(), -1, -1
            for yy in range(src.height()):
                for xx in range(src.width()):
                    c = src.pixelColor(xx, yy)
                    # Preserve antialiasing, but strengthen original ink.
                    strength = 255 - min(c.red(), c.green(), c.blue())
                    alpha = round(c.alpha() * max(0, min(1, (strength-15)/175)))
                    if alpha:
                        col = QColor(ink)
                        col.setAlpha(alpha)
                        mask.setPixelColor(xx, yy, col)
                        if alpha > 24:
                            left, top = min(left, xx), min(top, yy)
                            right, bottom = max(right, xx), max(bottom, yy)
            if right >= left and bottom >= top:
                mask = mask.copy(left, top, right-left+1, bottom-top+1)
            self._fi_crisp_cache[day] = QPixmap.fromImage(mask)
        logo = self._fi_crisp_cache[day]
        if logo.isNull():
            return
        ratio = logo.width() / logo.height()
        width = min(520, w * .30, h * .105 * ratio)
        height = width / ratio
        margin = max(12, int(w * .022))
        target = QRectF(w - margin - width, max(10, h * .018), width, height)
        p.save()
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        # One clean rendering pass, without offset copies or glow.
        p.drawPixmap(target, logo, QRectF(logo.rect()))
        p.restore()

    def paintEvent(self, event):
        if getattr(self, '_arcade_active', False):
            painter = QPainter(self)
            snapshot = self._arcade_snapshot
            if snapshot is not None and not snapshot.isNull():
                painter.drawPixmap(self.rect(), snapshot, snapshot.rect())
            else:
                painter.fillRect(self.rect(), QColor('#07111F'))
            painter.fillRect(self.rect(), QColor(0, 0, 0, round(255 * self._arcade_dim)))
            painter.end()
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(self.rect(), QColor(day_color('#030C1C', '#E8EFF5')))
        if w < 2 or h < 2:
            p.end()
            return

        # Grilla de pantalla completa, con divisiones mayores.
        step = max(34, int(w / 30))
        p.setPen(QPen(QColor(14, 73, 112, 105) if not is_day() else QColor(170, 191, 210, 105), 1))
        for x in range(0, w + step, step):
            p.drawLine(x, 0, x, h)
        for y in range(0, h + step, step):
            p.drawLine(0, y, w, y)
        p.setPen(QPen(QColor(23, 93, 139, 45) if not is_day() else QColor(150, 174, 195, 70), 1))
        for x in range(0, w + step, step * 5):
            p.drawLine(x, 0, x, h)
        for y in range(0, h + step, step * 5):
            p.drawLine(0, y, w, y)

        # Tres ondas animadas a lo ancho de la pantalla.
        period = max(220, w * .275)
        self._wave(p, 'sine', h * .18, h * .075, period, day_color('#1DF5FF', '#007F9C'), .5)
        self._wave(p, 'square', h * .58, h * .06, period * .79, day_color('#FF31CE', '#AD278F'), .8)
        self._wave(p, 'triangle', h * .87, h * .095, period * .87, day_color('#B46CFF', '#7545BC'), .4)

        # Velo oscuro central: legibilidad sin tapar las ondas del fondo.
        gradient = QLinearGradient(0, h * .25, 0, h * .84)
        gradient.setColorAt(0, QColor(232, 239, 245, 0) if is_day() else QColor(3, 10, 26, 0))
        gradient.setColorAt(.25, QColor(232, 239, 245, 170) if is_day() else QColor(3, 10, 26, 170))
        gradient.setColorAt(.68, QColor(232, 239, 245, 150) if is_day() else QColor(3, 10, 26, 150))
        gradient.setColorAt(1, QColor(232, 239, 245, 0) if is_day() else QColor(3, 10, 26, 0))
        p.fillRect(QRectF(0, h * .25, w, h * .59), gradient)

        # Ornamentos y trazo de pulso sobre el título.
        cx = w / 2
        title_y = h * .48
        pulse = QPainterPath()
        px, py = cx - 100, h * .30
        pulse.moveTo(px, py)
        for dx, dy in ((65, 0), (75, -15), (90, 20), (107, -52),
                       (126, 28), (142, 0), (200, 0)):
            pulse.lineTo(px + dx, py + dy)
        self._glow_path(p, pulse, day_color('#24F6FF', '#007F9C'), 2.5)

        # Título ajustado al ancho real con métricas de fuente (no tamaño fijo).
        title = 'OSCILOSCOPIO'
        title_font, sub_font = self._fonts_for_width(w)
        self._centered_text(p, title, cx, title_y, title_font, day_color('#A9FCFF', '#183149'), day_color('#00EFFF', '#007F9C'))

        # Esquinas violetas que enmarcan el título.
        tw = QFontMetricsF(title_font).horizontalAdvance(title)
        left = cx - tw / 2 - 28
        right = cx + tw / 2 + 28
        top = title_y - QFontMetricsF(title_font).ascent() * .9
        bottom = title_y + 6
        for x, direction in ((left, 1), (right, -1)):
            corner = QPainterPath()
            corner.moveTo(x + 55 * direction, top)
            corner.lineTo(x + 12 * direction, top)
            corner.quadTo(x, top, x, top + 12)
            corner.lineTo(x, bottom - 10)
            self._glow_path(p, corner, day_color('#A16BFF', '#7545BC'), 2)

        subtitle = 'SISTEMA DE ADQUISICIÓN Y VISUALIZACIÓN DE SEÑALES'
        self._centered_text(p, subtitle, cx, h * .55, sub_font, day_color('#E5F3FF', '#40576D'))
        underline = QPainterPath()
        underline.moveTo(cx - min(155, w * .13), h * .585)
        underline.lineTo(cx + min(155, w * .13), h * .585)
        self._glow_path(p, underline, day_color('#24F6FF', '#007F9C'), 2)

        # Soft local veil behind credits (no solid rectangle).
        from PySide6.QtCore import QSettings
        credits_day = QSettings('OsciloscopioPF', 'Osciloscopio').value('appearance/theme', 'dark') == 'light'
        veil_rgb = (232,239,245) if credits_day else (3,10,26)
        veil = QLinearGradient(w*.22, 0, w*.78, 0)
        for stop, alpha in ((0,0),(.2,195),(.8,195),(1,0)):
            veil.setColorAt(stop, QColor(*veil_rgb, alpha))
        p.fillRect(QRectF(w*.22, h*.63, w*.56, h*.15), veil)

        # Autor con nombre fucsia.
        author_font = QFont('Segoe UI', max(10, min(22, int(min(w / 70, h / 30)))))
        p.setFont(author_font)
        fm = QFontMetricsF(author_font)
        first, second = 'Desarrollado por ', 'Rocío Aparicio Vera'
        tx = cx - (fm.horizontalAdvance(first) + fm.horizontalAdvance(second)) / 2
        ay = h * .685
        p.setPen(QColor(day_color('#ECF4FF', '#40576D')))
        p.drawText(int(tx), int(ay), first)
        p.setPen(QColor(day_color('#FF39D5', '#AD278F')))
        p.drawText(int(tx + fm.horizontalAdvance(first)), int(ay), second)

        # IDENTIDAD_ACADEMICA_FI_V1
        from PySide6.QtCore import QSettings
        day = QSettings('OsciloscopioPF', 'Osciloscopio').value('appearance/theme', 'dark') == 'light'
        academic_font = QFont('Segoe UI', max(9, min(16, int(min(w / 95, h / 45)))))
        self._centered_text(p, 'Proyecto Final – Ingeniería Electrónica',
                            cx, h * .731, academic_font,
                            '#40576D' if day else '#C4D5E8')
        year_font = QFont('Segoe UI', max(8, academic_font.pointSize() - 2))
        self._centered_text(p, 'Año 2026', cx, h * .765, year_font,
                            '#526B83' if day else '#A0B5CB')
        self._draw_institution_logo(p, w, h)

        # Halo bajo el botón real, sin bloquear sus clics.
        br = self.start_button.geometry()
        halo = QPainterPath()
        halo.addRoundedRect(QRectF(br.adjusted(-2, -2, 2, 2)), 30, 30)
        self._glow_path(p, halo, day_color('#00F0FF', '#007F9C'), 2)
        p.end()
